function renderTimeline(){
 const ruler=$('#ruler');ruler.innerHTML='';const step=project.duration<=20?2:project.duration<=60?5:30;for(let t=0;t<=project.duration;t+=step){const n=document.createElement('span');n.style.left=`${t/project.duration*100}%`;n.textContent=`${t.toFixed(0)}s`;ruler.append(n);}
 $('#clips').innerHTML='';const source=project.referenceKind==='builtin'&&project.keyframes.length===15?phases.map(x=>({...x,start:x.start/15.2*project.duration,end:x.end/15.2*project.duration})):project.keyframes.slice(0,-1).map((k,i)=>({start:k.time,end:project.keyframes[i+1].time,label:k.label,color:phases[i%8].color}));for(const ph of source){const el=document.createElement('div');el.className='clip';el.style.flex=`${ph.end-ph.start} 0 0`;el.style.setProperty('--clip',ph.color);const label=document.createElement('span');label.textContent=ph.label;el.append(label);$('#clips').append(el);}
 $('#key-lane').innerHTML='';for(const k of project.keyframes){const el=document.createElement('button');el.className='key-dot'+(k.id===selected?' selected':'');el.style.left=`${k.time/project.duration*100}%`;el.dataset.id=k.id;el.title=`${k.label} · ${k.time.toFixed(2)}s`;el.setAttribute('aria-label',`${k.label}关键帧`);$('#key-lane').append(el);}
 $('#frame-count').textContent=`${project.keyframes.length} 个关键帧 · ${project.fps} FPS`;updateTransport();
}
function setView(next){view=next;scene.mode=next==='director'?'director':'camera';scene.controls.enabled=next==='director';$('#viewport').classList.toggle('camera-mode',next==='camera');$('#viewport').classList.toggle('compare-mode',next==='compare');$('#viewport-title').textContent=next==='director'?'自由观察':next==='compare'?'模型预演':'镜头画面';$('#orbit-tip').textContent=next==='director'?'拖动旋转 · 滚轮缩放 · 右键平移':'点击时间轴跳转 · 空格播放 / 暂停';$$('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===next));scene.resize();syncReference(true);}
function download(data,name,type){const blob=data instanceof Blob?data:new Blob([data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function closeModal(){if(recording)return;$('#modal-root').innerHTML='';}
function openModal(title,body){$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-header"><h2>${title}</h2><button class="icon-btn modal-close" aria-label="关闭">${I('x')}</button></div>${body}</section></div>`;$('.modal-close').onclick=closeModal;$('.modal-backdrop').onclick=e=>{if(e.target===$('.modal-backdrop'))closeModal();};iconize();$('.modal-close').focus();}
function exportModal(){openModal('把想法带到下一步',`<p>所有文件直接保存到你的设备，不经过云端上传。</p><button class="export-option" data-export="project">${I('file-json')}<div><strong>工程文件</strong><span>JSON · 保留关键帧、镜头参数与场景设置</span></div>${I('download')}</button><label class="export-format">视频格式<select id="video-format"><option value="mp4" selected>MP4（默认）</option><option value="webm">WebM（实时录制）</option></select></label><button class="export-option" data-export="video">${I('video')}<div><strong>预演视频</strong><span>MP4 默认 · 720p · 逐帧输出，不丢帧</span></div>${I('download')}</button><button class="export-option" data-export="image">${I('image')}<div><strong>当前镜头画面</strong><span>PNG · 不包含界面与路径辅助线</span></div>${I('download')}</button><button class="export-option" data-export="prompt">${I('film')}<div><strong>分镜提示词</strong><span>TXT · 相机位置、时间、焦距与动作描述</span></div>${I('download')}</button><p>本浏览器工程库会恢复视频和模型；单独导出的 JSON 不含素材，跨设备需补充。MP4 优先 H.264，编码器不支持时使用 VP9 封装。</p>`);$$('[data-export]').forEach(b=>b.onclick=async()=>{const type=b.dataset.export;if(type==='project'){download(JSON.stringify(project,null,2),'rayspace-project.json','application/json');closeModal();toast('工程已导出，下次可用「打开工程」继续编辑');}if(type==='prompt'){download(promptFor(project),'rayspace-shot-list.txt','text/plain;charset=utf-8');closeModal();toast('分镜提示词已导出');}if(type==='image'){scene.update(time);const a=document.createElement('a');a.href=scene.screenshot();a.download=`rayspace-frame-${time.toFixed(2)}.png`;a.click();closeModal();toast('镜头画面已导出');}if(type==='video'){const format=$('#video-format').value;closeModal();startVideoExport(format);}});}
function startLegacyRecording(){
 if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream){toast('当前浏览器不支持视频录制，请使用较新的 Chrome 或 Edge',true);return;}
 const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!mime){toast('当前浏览器不支持 WebM 录制，请使用 Chrome 或 Edge',true);return;}
 let recorder,stream;try{
  recordState={time,playing,speed};togglePlay(false);speed=1;setTime(0);const canvas=scene.startExport();scene.update(0);stream=canvas.captureStream(24);recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:5000000});
 }catch(e){scene.stopExport();stream?.getTracks().forEach(t=>t.stop());toast(`录制无法启动：${e.message}`,true);return;}
 const parts=[];let cancelled=false;recorder.ondataavailable=e=>{if(e.data.size)parts.push(e.data);};
 openModal('正在录制运镜预演',`<p>正在本机录制，请保持此标签页在前台。完成后会自动下载 WebM 视频。</p><div class="export-progress"><div id="record-bar"></div></div><p id="record-time">0.0 / ${project.duration.toFixed(1)} 秒</p><button id="cancel-record" class="text-btn">取消录制</button>`);
 recording=true;scene.locked=true;$('#cancel-record').onclick=()=>{cancelled=true;stopRecording();};
 recorder.onstop=()=>{recordingMode=null;stream.getTracks().forEach(t=>t.stop());scene.stopExport();recording=false;scene.locked=false;closeModal();if(!cancelled&&parts.length){download(new Blob(parts,{type:mime}),'rayspace-previs.webm',mime);toast('运镜预演视频已导出');}const old=recordState;speed=old.speed;setTime(old.time);togglePlay(false);recordState=null;};
 recorder.onerror=()=>{cancelled=true;stopRecording();toast('视频录制失败，请缩短时长后重试',true);};
 window.stopRecording=(cancel=false)=>{if(cancel)cancelled=true;if(recorder.state!=='inactive')recorder.stop();togglePlay(false);};
 recorder.start(200);togglePlay(true);
}
const stopRecording=(cancel=false)=>window.stopRecording?.(cancel);
function showHelp(){openModal('从参考视频到你的镜头',`<p>01　每次导入视频都会新建一个独立工程。左侧按缩略图、文件名、编号和日期区分；视频、模型与机位保存在本浏览器，重开可恢复。</p><p>02　导入后自动识别人，并剔除主体区域后追踪背景特征，估计画面平移、尺度与滚转，生成模型机位。非人物可在第一帧框选主体。低可信度和疑似剪辑会标记出来；单目视频不能唯一求出物理尺度和焦距，不能保证与真实机位完全一致。</p><p>03　选择菱形关键帧，用 XYZ 手柄移动机位或瞄准点。使用 0.001m 步长、数值输入或拖动坐标标签精调。连续平滑曲线减少关键帧交界处的速度突变。</p><p>04　视频默认导出真正的 MP4，逐帧渲染；优先 H.264，设备不支持时使用 VP9。WebM 保留为可选格式。JSON 不包含原素材，跨设备需补充视频和 GLB。</p><div class="shortcut-list"><span>播放 / 暂停；逐帧</span><kbd>SPACE / ← →</kbd><span>移动机位 / 瞄准点</span><kbd>G / T</kbd><span>平移 / 升降</span><kbd>WASD / Q E</kbd><span>精调 / 快移</span><kbd>Shift ×0.1 / Alt ×10</kbd><span>约束拖拽轴；解除约束</span><kbd>X Y Z / Esc</kbd><span>前视 / 侧视 / 顶视；聚焦</span><kbd>1 / 3 / 7 / F</kbd><span>上一 / 下一关键帧</span><kbd>[ / ]</kbd><span>撤销 / 重做；导出工程</span><kbd>Ctrl Z / Shift Z / S</kbd></div><p>Higgsfield 仍为外部页面入口与分镜提示词，不会自动上传或付费生成。</p>`);}

