function storageFailure(err){$('#save-status').textContent='本机保存失败';toast(`本机存储失败：${err.message}。请导出工程备份或清理浏览器存储。`,true);}
function currentRecord(){const old=records.find(r=>r.id===project.id);return{id:project.id,project:structuredClone(project),poster:currentPoster,createdAt:old?.createdAt||Date.now(),updatedAt:Date.now()};}
async function saveCurrentNow(){clearTimeout(libraryTimer);const record=currentRecord();saveChain=saveChain.catch(()=>{}).then(()=>library.save(record));await saveChain;const i=records.findIndex(r=>r.id===record.id);if(i>=0)records[i]=record;else records.push(record);renderLibrary();return record;}
async function initializeLibrary(){
 try{records=await library.list();const active=localStorage.getItem(ACTIVE),existing=records.find(r=>r.id===active);if(existing){libraryReady=true;await activateProject(existing.id,false);}else{await library.save(currentRecord());records=await library.list();libraryReady=true;renderLibrary();persist();if(migratedLegacy)toast('旧版机位已保留。旧版没有存储原视频，请为此工程补充参考视频。');}return true;}catch(e){libraryReady=false;storageFailure(e);return false;}
}
function renderLibrary(){
 const list=$('#project-list'),filter=$('#project-search').value.toLocaleLowerCase();list.replaceChildren();const sorted=[...records].sort((a,b)=>b.createdAt-a.createdAt);
 for(const r of sorted){const p=r.project;if(filter&&!`${p.name} ${p.referenceName}`.toLocaleLowerCase().includes(filter))continue;const row=document.createElement('div');row.className='project-row'+(p.id===project.id?' active':'');row.dataset.projectId=p.id;row.setAttribute('role','listitem');const open=document.createElement('button');open.className='project-open';open.title=`${p.name}\n${p.referenceName}\n#${p.id.slice(0,6)}`;const image=document.createElement('img');image.src=r.poster||BUILTIN_POSTER;image.alt='工程缩略图';const info=document.createElement('div'),name=document.createElement('strong');name.textContent=p.name;const meta=document.createElement('span');meta.textContent=`${p.duration.toFixed(1)}s · #${p.id.slice(0,4)} · ${new Date(r.createdAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}`;const state=document.createElement('small');state.textContent=p.analysis?(p.analysis.usable?(p.analysis.coverage>=.6?'已自动匹配':'初步匹配 · 需校正'):'低可信 · 待校正'):p.referenceKind==='builtin'?'示例工程':p.referenceKind==='none'?'待补充视频':'待分析';info.append(name,meta,state);open.append(image,info);open.onclick=()=>activateProject(p.id).catch(e=>toast(e.message,true));const del=document.createElement('button');del.className='project-delete';del.textContent='×';del.title='删除此工程';del.setAttribute('aria-label',`删除工程 ${p.name}`);del.onclick=()=>{openModal('删除这个工程？','<p id="delete-project-name"></p><p>将删除本浏览器中此工程的机位、参考视频和模型。其他工程不受影响。</p><button class="text-btn" id="confirm-delete-project">确认删除</button>');$('#delete-project-name').textContent=p.name;$('#confirm-delete-project').onclick=async()=>{closeModal();if(p.id===project.id){analysisController?.abort();clearTimeout(libraryTimer);}await saveChain.catch(()=>{});await library.remove(p.id);records=records.filter(x=>x.id!==p.id);if(project.id===p.id){if(records.length)await activateProject(records[0].id,false);else await addProject(defaultProject(),{poster:BUILTIN_POSTER,saveOld:false});}renderLibrary();};};row.append(open,del);list.append(row);}
 if(!list.children.length){const note=document.createElement('p');note.className='helper';note.textContent='没有匹配的工程';list.append(note);}
}
async function addProject(p,{videoBlob,poster,saveOld=true}={}){
 if(!libraryReady)throw new Error('工程库尚未就绪，无法安全建立新工程');if(saveOld)await saveCurrentNow();p=validateProject(p);const record={id:p.id,project:p,poster:poster||BUILTIN_POSTER,createdAt:Date.now(),updatedAt:Date.now()};
 try{if(videoBlob)await library.putAsset(p.id,'video',videoBlob);await library.save(record);}catch(e){await library.remove(p.id).catch(()=>{});throw e;}
 records.push(record);await activateProject(p.id,false);
}
async function activateProject(id,saveOld=true){
 if(recording||loadingProject){toast('请等待当前导入或导出完成');return;}analysisController?.abort();if(saveOld&&libraryReady)await saveCurrentNow();const record=await library.get(id);if(!record)throw new Error('工程不存在或已删除');loadingProject=true;
 try{togglePlay(false);clearTimeout(libraryTimer);project=validateProject(record.project);history=[];future=[];time=0;selected=project.keyframes[0].id;currentPoster=record.poster||BUILTIN_POSTER;if(videoURL){URL.revokeObjectURL(videoURL);videoURL=null;}const blob=await library.asset(id,'video');video.pause();
  if(blob){videoURL=URL.createObjectURL(blob);video.src=videoURL;}else if(project.referenceKind==='builtin')video.src=BUILTIN_VIDEO;else video.removeAttribute('src');video.load();
  $('#ref-name').textContent=project.referenceKind==='none'?'待补充原参考视频':project.referenceName;$('#ref-poster').src=currentPoster;$('#ref-details').textContent=`${project.duration.toFixed(1)}s · #${project.id.slice(0,6)}`;scene.clearCustom();modelName='街头人物';const model=await library.asset(id,'model');if(model){try{await scene.importGLB(model);modelName=project.modelName||model.name||'本机 GLB 模型';}catch(e){toast(`此工程的模型无法恢复：${e.message}`,true);}}$('#model-name').textContent=modelName;$('#model-description').textContent=model?'已从此工程恢复':'内置模型 · 可替换';refreshAll();renderLibrary();
 }finally{loadingProject=false;}
}
$('#project-search').oninput=renderLibrary;
async function runAnalysis(){
 if(recording||loadingProject||project.referenceKind==='none'){toast('请先补充有效参考视频',true);return;}
 analysisController?.abort();const controller=new AbortController();analysisController=controller;const id=project.id,source=video.src;togglePlay(false);$('#analysis-progress').classList.remove('hidden');$('#analyze-video').disabled=true;
 try{
  const result=await analyzeMotion({src:source,seedBox:project.subjectBox,signal:controller.signal,density:+$('#analysis-density').value,onProgress:state=>{if(project.id!==id)return;$('#analysis-progress-bar')?.style.setProperty('width',`${state.progress*100}%`);$('#analysis-progress .analysis-progress-bar span').style.width=`${state.progress*100}%`;$('#analysis-status').textContent=`${state.frame}/${state.total} 帧 · ${state.subject==='person'?'已识别人':state.subject==='manual'?'指定主体':'跟踪主体与背景'}`;}});
  if(project.id!==id||controller.signal.aborted)return;remember();project.analysis=result;if(result.usable){const poses=reconstructCamera(result,project);project.keyframes=poses.keyframes;project.subjectPath=poses.subjectPath;project.subjectMotion=false;project.easing='smooth';selected=project.keyframes[0].id;time=0;toast(`已根据此视频生成 ${poses.keyframes.length} 个机位，背景有效覆盖 ${Math.round(result.coverage*100)}%`);}else toast('背景纹理不足或运动过快，无法可靠匹配。已标记待校正，不套用示例运镜。',true);
  refreshAll();await saveCurrentNow();
 }catch(e){if(e.name!=='AbortError')toast(`运镜分析失败：${e.message}`,true);}finally{if(analysisController===controller){analysisController=null;$('#analysis-progress').classList.add('hidden');$('#analyze-video').disabled=false;}}
}
function renderAnalysis(){
 const a=project.analysis,el=$('#analysis-result'),strip=$('#thumb-strip');strip.replaceChildren();strip.classList.toggle('hidden',!a?.thumbs?.length);if(!a){el.classList.add('hidden');return;}el.classList.remove('hidden');
 const f=a.frames.reduce((best,f)=>Math.abs(f.time-time/project.duration*a.duration)<Math.abs(best.time-time/project.duration*a.duration)?f:best,a.frames[0]);
 el.textContent=`${a.subjectDetected?'已识别人':a.manualSubject?'已指定主体':'主体类别未识别'} · 背景有效覆盖 ${Math.round(a.coverage*100)}%\n${a.frames.length} 帧 / ${a.frames.filter(f=>f.cut).length} 处疑似切换 · 当前可信度 ${Math.round((f?.confidence||0)*100)}%\n${a.usable?(a.coverage>=.6?'已自动生成可编辑三维机位。':'已初步生成机位，低可信片段请校正。'):'背景信息不足，保留原机位供手动校正。'}${a.modelError?' 人体模型未能运行，当前仅为运动区域跟踪。':''}\n单目视频无法唯一确定真实焦距、深度与物理距离。`;
 for(const t of a.thumbs||[]){const img=document.createElement('img');img.src=t.url;img.alt=`参考帧 ${t.time.toFixed(1)}s`;img.title=img.alt;img.onclick=()=>{togglePlay(false);setTime(t.time/a.duration*project.duration);setView('compare');};strip.append(img);}
}
function setTool(kind){editKind=kind;scene.setEditTool(kind);$('#tool-position').classList.toggle('active',kind==='position');$('#tool-target').classList.toggle('active',kind==='target');}
function setAxis(axis){axisLock=axisLock===axis?null:axis;scene.setAxis(axisLock);$$('[data-lock]').forEach(b=>b.classList.toggle('active',b.dataset.lock===axisLock));}
function nudge(axis,direction,e={}){const step=(nudgeStep||.01)*(e.shiftKey?.1:e.altKey?10:1);applyEdit(()=>{key()[editKind][axis]=+(key()[editKind][axis]+direction*step).toFixed(5);time=key().time;});}
$('#tool-position').onclick=()=>setTool('position');$('#tool-target').onclick=()=>setTool('target');$$('[data-lock]').forEach(b=>b.onclick=()=>setAxis(b.dataset.lock));$('#snap-step').onchange=e=>{nudgeStep=+e.target.value;scene.setSnap(nudgeStep);};$('#viewpoint').onchange=e=>{if(e.target.value!=='free'){setView('director');scene.setViewpoint(e.target.value);}};$('#focus-key').onclick=()=>{setView('director');scene.focusSelected();};$$('[data-nudge]').forEach(b=>b.onclick=e=>{const[a,d]=b.dataset.nudge.split(':').map(Number);nudge(a,d,e);});
$('#orbit-left').onclick=e=>applyEdit(()=>{key().position=orbitPose(key(),e.shiftKey?-.1:-1,0);time=key().time;});$('#orbit-right').onclick=e=>applyEdit(()=>{key().position=orbitPose(key(),e.shiftKey?.1:1,0);time=key().time;});
function handleShortcut(e){
 if(recording||loadingProject)return;if(e.key==='Escape'){if(subjectSelecting){subjectSelecting=false;$('#tracking-overlay').classList.remove('selecting');}scene.gizmo.reset();setAxis(null);closeModal();$('.leftbar').classList.remove('open');$('.inspector').classList.remove('open');return;}
 if(/INPUT|SELECT|TEXTAREA/.test(document.activeElement.tagName)||$('.modal-backdrop'))return;
 if(e.key==='Shift'||e.key==='Alt'){scene.gizmo.setTranslationSnap(nudgeStep?(nudgeStep*(e.key==='Shift'?.1:10)):null);return;}const mod=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(mod&&k==='z'){e.preventDefault();$(e.shiftKey?'#redo':'#undo').click();return;}if(mod&&k==='s'){e.preventDefault();download(JSON.stringify(project,null,2),'rayspace-project.json','application/json');return;}
 if(e.code==='Space'){e.preventDefault();togglePlay();return;}if(k==='arrowright'||k==='arrowleft'){e.preventDefault();togglePlay(false);setTime(time+(k==='arrowright'?1:-1)/24);return;}
 if(mod)return;const move={a:[0,-1],d:[0,1],s:[1,-1],w:[1,1],q:[2,-1],e:[2,1]};if(move[k]){e.preventDefault();togglePlay(false);nudge(...move[k],e);return;}
 if(k==='g')setTool('position');if(k==='t')setTool('target');if(['x','y','z'].includes(k))setAxis(k.toUpperCase());if(k==='f')$('#focus-key').click();if(['1','3','7'].includes(k)){setView('director');scene.setViewpoint({'1':'front','3':'side','7':'top'}[k]);}if(k==='['||k===']'){const i=project.keyframes.findIndex(k=>k.id===selected),j=clamp(i+(k===']'?1:-1),0,project.keyframes.length-1);selectKey(project.keyframes[j].id);}
}
// Scrub axis labels without losing precision; one undo entry per drag.
$$('.coord b').forEach(label=>label.addEventListener('pointerdown',e=>{if(recording)return;e.preventDefault();const input=label.parentElement.querySelector('input'),field=input.dataset.vector,axis=+input.dataset.axis,start=key()[field][axis],origin=e.clientX;remember();togglePlay(false);time=key().time;label.setPointerCapture(e.pointerId);const move=ev=>{const step=ev.shiftKey?.001:ev.altKey?.1:.01;const value=clamp(start+(ev.clientX-origin)*step,-999,999);if(Math.hypot(...key().position.map((v,j)=>(field==='position'&&j===axis?value:v)-(field==='target'&&j===axis?value:key().target[j])))<.01)return;key()[field][axis]=+value.toFixed(4);input.value=key()[field][axis];scene.rebuildPath();};const up=()=>{label.removeEventListener('pointermove',move);label.removeEventListener('pointerup',up);label.removeEventListener('pointercancel',up);persist();};label.addEventListener('pointermove',move);label.addEventListener('pointerup',up);label.addEventListener('pointercancel',up);}));
function overlayRect(){const el=$('#tracking-overlay'),w=el.clientWidth,h=el.clientHeight,ratio=video.videoWidth/video.videoHeight;if(!ratio)return null;const vw=Math.min(w,h*ratio),vh=vw/ratio;return{x:(w-vw)/2,y:(h-vh)/2,w:vw,h:vh};}
let selectionStart=null,selectionEnd=null;
$('#pick-subject').onclick=()=>{if(project.referenceKind==='none'){toast('请先补充参考视频',true);return;}togglePlay(false);setView('compare');setTime(0);subjectSelecting=true;$('#tracking-overlay').classList.add('selecting');toast('在第一帧拖出主体范围；Esc 取消。随后会重新匹配机位。');};
const overlay=$('#tracking-overlay');overlay.addEventListener('pointerdown',e=>{if(!subjectSelecting)return;const r=overlay.getBoundingClientRect();selectionStart=selectionEnd={x:e.clientX-r.left,y:e.clientY-r.top};overlay.setPointerCapture(e.pointerId);});overlay.addEventListener('pointermove',e=>{if(!selectionStart)return;const r=overlay.getBoundingClientRect();selectionEnd={x:e.clientX-r.left,y:e.clientY-r.top};});overlay.addEventListener('pointerup',()=>{if(!selectionStart||!selectionEnd)return;const r=overlayRect();if(r){const x=clamp((Math.min(selectionStart.x,selectionEnd.x)-r.x)/r.w,0,1),y=clamp((Math.min(selectionStart.y,selectionEnd.y)-r.y)/r.h,0,1),w=clamp(Math.abs(selectionEnd.x-selectionStart.x)/r.w,0,1-x),h=clamp(Math.abs(selectionEnd.y-selectionStart.y)/r.h,0,1-y);if(w>.03&&h>.03){project.subjectBox={x,y,w,h};persist();analysisPromise=runAnalysis();}else toast('选区太小，请重新框选',true);}selectionStart=selectionEnd=null;subjectSelecting=false;overlay.classList.remove('selecting');});
function drawTracking(){
 if(view!=='compare')return;const r=overlayRect();if(!r)return;const w=overlay.clientWidth,h=overlay.clientHeight;if(overlay.width!==w||overlay.height!==h){overlay.width=w;overlay.height=h;}const ctx=overlay.getContext('2d');ctx.clearRect(0,0,w,h);
 if(selectionStart&&selectionEnd){ctx.strokeStyle='#f4bd88';ctx.lineWidth=2;ctx.strokeRect(selectionStart.x,selectionStart.y,selectionEnd.x-selectionStart.x,selectionEnd.y-selectionStart.y);return;}
 const a=project.analysis;if(!a?.frames?.length)return;const t=time/project.duration*a.duration,f=a.frames.reduce((a,b)=>Math.abs(b.time-t)<Math.abs(a.time-t)?b:a);if($('#show-tracks').checked){ctx.strokeStyle='#89c6b2';for(const p of f.points||[]){ctx.beginPath();ctx.moveTo(r.x+p[0]*r.w,r.y+p[1]*r.h);ctx.lineTo(r.x+p[2]*r.w,r.y+p[3]*r.h);ctx.stroke();ctx.fillStyle='#91d4b7';ctx.fillRect(r.x+p[2]*r.w-1,r.y+p[3]*r.h-1,2,2);}}
 if(f.box){const b=f.box,x=r.x+b.x*r.w,y=r.y+b.y*r.h;ctx.strokeStyle=b.kind==='person'?'#f0ba83':'#91bace';ctx.lineWidth=1.5;ctx.strokeRect(x,y,b.w*r.w,b.h*r.h);ctx.fillStyle='#162226d9';ctx.fillRect(x,Math.max(r.y,y-20),Math.min(150,b.w*r.w+50),20);ctx.fillStyle='#f5d0a9';ctx.font='11px sans-serif';ctx.fillText(`${b.kind==='person'?'人物主体':b.kind==='manual'?'指定主体':'运动区域'} ${Math.round(b.score*100)}%`,x+5,Math.max(r.y+14,y-6));}
}
async function startVideoExport(format='mp4'){
 if(format==='webm'){recordingMode='realtime';startLegacyRecording();return;}const before={time,speed};togglePlay(false);exportController=new AbortController();openModal('导出 MP4 预演',`<p>按相机时间逐帧渲染，不依赖设备的实时播放帧率。完成后直接保存到你的设备。</p><div class="export-progress"><div id="record-bar"></div></div><p id="record-time">正在检查编码器…</p><button id="cancel-record" class="text-btn">取消导出</button>`);recording=true;recordingMode='frames';scene.locked=true;$('#cancel-record').onclick=()=>exportController.abort();
 try{const result=await encodeMP4({scene,project,signal:exportController.signal,onFrame:t=>{time=t;},onProgress:s=>{$('#record-bar').style.width=`${s.progress*100}%`;$('#record-time').textContent=`${s.frame}/${s.total} 帧 · MP4 / ${s.codec}`;}});download(result.blob,`${project.name.replace(/[\\/:*?"<>|]/g,'-')}-previs.mp4`,'video/mp4');toast(`MP4 已导出 · ${result.codec} · ${result.frames} 帧`);}catch(e){if(e.name!=='AbortError')toast(`MP4 导出失败：${e.message}`,true);else toast('MP4 导出已取消');}finally{recording=false;recordingMode=null;scene.locked=false;closeModal();speed=before.speed;setTime(before.time);scene.update(time);exportController=null;}
}

$('#previous-key').onclick=()=>{const i=project.keyframes.findIndex(k=>k.id===selected);selectKey(project.keyframes[Math.max(0,i-1)].id);};$('#next-key').onclick=()=>{const i=project.keyframes.findIndex(k=>k.id===selected);selectKey(project.keyframes[Math.min(project.keyframes.length-1,i+1)].id);};
const numericDrafts=new WeakMap();$$('[data-vector]').forEach(input=>{input.onfocus=()=>{numericDrafts.set(input,JSON.stringify(project));togglePlay(false);time=key().time;};input.oninput=()=>{const n=input.valueAsNumber;if(!Number.isFinite(n)||Math.abs(n)>999)return;const field=input.dataset.vector,axis=+input.dataset.axis;const p=[...key().position],t=[...key().target];(field==='position'?p:t)[axis]=n;if(Math.hypot(...p.map((v,i)=>v-t[i]))<.01)return;key()[field][axis]=n;scene.rebuildPath();};input.onchange=()=>{const before=numericDrafts.get(input);try{project=validateProject(project);scene.setProject(project);if(before&&before!==JSON.stringify(project)){history.push(before);future=[];}persist();}catch(e){if(before)project=JSON.parse(before);refreshAll();toast(e.message,true);}numericDrafts.set(input,JSON.stringify(project));};input.addEventListener('keydown',e=>{if(e.key==='Escape'){e.stopPropagation();const before=numericDrafts.get(input);if(before)project=JSON.parse(before);numericDrafts.delete(input);input.blur();refreshAll();}});});

window.addEventListener('keyup',e=>{if(e.key==='Shift'||e.key==='Alt')scene.gizmo.setTranslationSnap(nudgeStep||null);});
